<?php namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Http\Resources\EventResource; use App\Models\Event; use Illuminate\Http\Request; use Illuminate\Support\Facades\Cache; class EventController extends Controller {public function index(Request $r){$key='events:'.md5($r->fullUrl());$data=Cache::tags(['events'])->remember($key,60,fn()=>Event::query()->upcoming()->city($r->query('city'))->category($r->query('category'))->with(['organizer:id,name','venue:id,name,city,address','ticketTypes'])->orderBy('starts_at')->paginate(20));return EventResource::collection($data);}public function show(Event $event){return new EventResource($event->load(['organizer:id,name','venue','ticketTypes']));}public function mine(Request $r){$data=Event::withoutGlobalScope('publicPublished')->where('organizer_id',$r->user()->id)->with(['venue','ticketTypes'])->orderByDesc('starts_at')->paginate(20);return EventResource::collection($data);}public function store(\App\Http\Requests\StoreEventRequest $r){$data=$r->validated();$cats=$data['ticket_categories'];unset($data['ticket_categories']);$data['organizer_id']=$r->user()->id;$data['status']=$data['status']??'draft';$e=Event::withoutGlobalScope('publicPublished')->create($data);foreach($cats as $c)$e->ticketTypes()->create($c);return (new EventResource($e->load(['venue','ticketTypes'])))->response()->setStatusCode(201);}public function update(\App\Http\Requests\UpdateEventRequest $r,Event $event){$event->update($r->validated());return new EventResource($event->fresh()->load('ticketTypes'));}public function cancel(Request $r,Event $event){abort_unless($event->organizer_id===$r->user()->id||$r->user()->role->value==='admin',403);if($event->status->value==='cancelled')return response()->json(['message'=>'الفعالية ملغاة مسبقًا']);$event->update(['status'=>'cancelled']);\App\Events\EventCancelled::dispatch($event);return response()->json(['message'=>'تم إلغاء الفعالية؛ بدأت إجراءات رد المبالغ بالخلفية.']);}}
